export const CYCLES={monthly:1,quarterly:3,semiannual:6,yearly:12};
export const CYCLE_LABELS={monthly:'Mensal',quarterly:'Trimestral',semiannual:'Semestral',yearly:'Anual'};
export const MAX_RECEIPT=2*1024*1024;
export function planPaid(p){return p.price>0||Object.values(p.billingPrices||{}).some(n=>n>0);}
export function quote(p,cycle){if(!CYCLES[cycle])throw Error('Periodicidade inválida.');const value=p.billingPrices?.[cycle]??(p.price||0)*CYCLES[cycle]/(CYCLES[p.period]||1);if(!Number.isFinite(value)||value<0||value>1000000)throw Error('Preço inválido.');return Math.round(value*100)/100;}
export function activeSubscription(s,targetId,now=Date.now()){return !!s&&s.targetId===targetId&&Number.isSafeInteger(s.validUntil)&&s.validUntil>now;}
export function teacherPlanActive(profile,plan,now=Date.now()){return !planPaid(plan)||activeSubscription(profile.planPayment,profile.planId||'free',now);}
export function renewUntil(previous,cycle,now=Date.now()){const n=CYCLES[cycle];if(!n)throw Error('Periodicidade inválida.');const d=new Date(Math.max(previous||0,now)),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,end));return d.getTime();}
export function validPercent(v){return Number.isFinite(v)&&v>=0&&v<=100;}
export function revenueShare(amount,mode,settings){if(!['royalties','sales'].includes(mode))throw Error('Modalidade inválida.');const percent=settings?.[mode]??0;if(!validPercent(percent))throw Error('Percentual inválido.');return{mode,percent,gross:amount,teacherAmount:Math.round(amount*percent)/100,platformAmount:Math.round((amount-Math.round(amount*percent)/100)*100)/100};}
export function validPrices(p){return !!p&&Object.keys(CYCLES).every(k=>Number.isFinite(p[k])&&p[k]>=0&&p[k]<=1000000);}
export function validCourse(c){return !!c&&typeof c.title==='string'&&c.title.trim().length>0&&c.title.length<=150&&typeof c.description==='string'&&c.description.length<=4000&&typeof c.free==='boolean'&&typeof c.published==='boolean'&&['royalties','sales'].includes(c.remunerationMode)&&validPrices(c.billingPrices)&&(c.free||Object.values(c.billingPrices).every(p=>p>0))&&typeof c.paymentInstructions==='string'&&c.paymentInstructions.length<=4000&&Array.isArray(c.subjects)&&c.subjects.length>=1&&c.subjects.length<=30&&new Set(c.subjects.map(s=>s?.subjectId)).size===c.subjects.length&&c.subjects.every(s=>s&&typeof s.subjectId==='string'&&/^[\w-]{1,128}$/.test(s.subjectId)&&typeof s.body==='string'&&s.body.length<=30000&&typeof s.url==='string'&&s.url.length<=2000&&(!s.url||/^https?:\/\//i.test(s.url)))&&JSON.stringify(c).length<=250000;}
export function receiptExtension(bytes,mime){if(mime==='application/pdf'&&bytes.subarray(0,5).toString()==='%PDF-')return'pdf';if(mime==='image/png'&&bytes.subarray(0,8).toString('hex')==='89504e470d0a1a0a')return'png';if(mime==='image/jpeg'&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255)return'jpg';return null;}
